-- 7ce7fad3 | ما حكم إقامة الحاكم لمصلحة يراها راجحة دون نص خاص فيها؟
UPDATE qa_questions SET
  answer = 'مشروعٌ ما دام محقِّقًا للعدل غيرَ مخالفٍ لما نطق به الشرع، وهو الذي يسمّيه ابن القيم في الطرق الحكمية «السياسة الشرعية»؛ نقل فيها عن ابن عقيل أن «السياسة ما كان فعلًا يكون معه الناس أقرب إلى الصلاح، وأبعد عن الفساد، وإن لم يضعه الرسول - صلى الله عليه وسلم -، ولا نزل به وحي»، ثم قيَّد قولَ من قال «لا سياسة إلا ما وافق الشرع» بأن مرادَه إن كان «لم يخالف ما نطق به الشرع: فصحيح»، وإن كان «لا سياسة إلا ما نطق به الشرع، فغلط، وتغليط للصحابة». وهو «موضع مَزَلَّة أقدام، ومضلة أفهام»: فرَّطت فيه طائفةٌ «فعطلوا الحدود، وضيعوا الحقوق»، «وجعلوا الشريعة قاصرة لا تقوم بمصالح العباد»، «وأفرطت طائفة أخرى» ... «فسوغت من ذلك ما ينافي حكم الله ورسوله». والضابطُ عنده: «فإذا ظهرت أمارات العدل وأسفر وجهه بأي طريق كان، فثم شرع الله ودينه»، «فأي طريق استخرج بها العدل والقسط فهي من الدين، وليست مخالفة له».',
  reference = 'الطرق الحكمية في السياسة الشرعية لابن القيم (ت نايف الحمد، دار عطاءات العلم): ج١/ص٢٩ (كلام ابن عقيل في السياسة الشرعية)، وج١/ص٣٠-٣١ (السياسة الشرعية بين الإفراط والتفريط) | الكلمات المفتاحية: تصرف الإمام منوط بالمصلحة',
  evidence = 'نقل ابن القيم عن ابن عقيل في الفنون: «جرى في جواز العمل في السلطنة بالسياسة الشرعية: أنه هو الحزم، ولا يخلو من القول به إمام. فقال شافعي: لا سياسة إلا ما وافق الشرع. فقال ابن عقيل: السياسة ما كان فعلًا يكون معه الناس أقرب إلى الصلاح، وأبعد عن الفساد، وإن لم يضعه الرسول - صلى الله عليه وسلم -، ولا نزل به وحي. فإن أردت بقولك: إلا ما وافق الشرع أي لم يخالف ما نطق به الشرع: فصحيح. وإن أردت: لا سياسة إلا ما نطق به الشرع، فغلط، وتغليط للصحابة» (ج١/ص٢٩). ثم قال ابن القيم: «وهذا موضع مَزَلَّة أقدام، ومضلة أفهام، وهو مقام ضنك، ومعترك صعب» (ج١/ص٣٠)، «فإن الله سبحانه أرسل رسله، وأنزل كتبه، ليقوم الناس بالقسط، وهو العدل الذي قامت به الأرض والسماوات، فإذا ظهرت أمارات العدل وأسفر وجهه بأي طريق كان، فثم شرع الله ودينه» (ج١/ص٣١)، «فلا يقال: إن السياسة العادلة مخالفة لما نطق به الشرع، بل هي موافقة لما جاء به، بل هي جزء من أجزائه» (ج١/ص٣١).',
  verification_status = 'verified'
WHERE id = '7ce7fad3-f411-473f-8ebc-ecc50e1ad188'
  AND reference = 'الطرق الحكمية لابن القيم | الكلمات المفتاحية: تصرف الإمام منوط بالمصلحة'
  AND evidence = 'مبحث فقهي أصيل في كتب السياسة الشرعية.'
  AND answer = 'مشروع ضمن نطاق السياسة الشرعية، فما لا نص فيه من أمور تنظيم الدولة يجوز لولي الأمر تقديره اجتهادًا بما يحقق المصلحة العامة ولا يخالف أصول الشريعة الثابتة.';

-- 984d613a | ما الضابط العام للمعاملات المالية؟
UPDATE qa_questions SET
  answer = 'ضابطُه عند ابن القيم في إعلام الموقعين أصلٌ مثبَتٌ لا نفيٌ مجرَّد: «الأصل في العقود والمعاملات الصحة حتى يقوم دليل على البطلان والتحريم»، بخلاف العبادات فـ«الأصل في العبادات البطلان حتى يقوم دليل على الأمر»؛ فما سكت عنه الشارع منها «فهي عفو حتى يحرمها»، ولا يبطُل منها إلا «ما أبطله الشارع أو نهى عنه». وقد أمر الله بالوفاء بها: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَوْفُوا۟ بِٱلْعُقُودِ﴾، ونهى عن أكل المال بالباطل مستثنيًا التجارةَ عن تراضٍ: ﴿لَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٍۢ مِّنكُمْ﴾، وحرَّم الربا بعينه: ﴿وَأَحَلَّ ٱللَّهُ ٱلْبَيْعَ وَحَرَّمَ ٱلرِّبَوٰا۟﴾. والغررُ المنهيُّ عنه محدَّدٌ لا مطلق، فهو «ما لا يُقْدَر على تسليمه، سواء كان موجودًا أو معدومًا»، «وهذا من الميْسِر الذي حرّمه اللَّه ورسوله».',
  reference = 'القرآن الكريم: النساء ٢٩، والمائدة ١، والبقرة ٢٧٥؛ إعلام الموقعين عن رب العالمين لابن القيم (ت مشهور بن حسن، دار ابن الجوزي): ج٣/ص١٠٧-١٠٨ (الأصل في العقود والشروط الصحة أو الفساد)، وج٣/ص٦٠ وص٢٠٧ (النهي إنما ورد في بيع الغرر لا بيع المعدوم) | الكلمات المفتاحية: معاملات، مال، غرر',
  evidence = 'قال ابن القيم في إعلام الموقعين وهو يعدّ أخطاء من أبطل معاملات الناس بلا دليل: «الخطأ الرابع لهم: اعتقادهم أن عقود المسلمين وشروطهم ومعاملاتهم كلها على البطلان حتى يقوم دليل على الصحة»، «فأفسدوا بذلك كثيرًا من معاملات الناس وعقودهم وشروطهم بلا برهان من اللَّه»، «وجمهور الفقهاء على خلافه، وأن الأصل في العقود والشروط الصحة إلا ما أبطله الشارع أو نهى عنه، وهذا القول هو الصحيح»، «فالأصل في العبادات البطلان حتى يقوم دليل على الأمر، والأصل في العقود والمعاملات الصحة حتى يقوم دليل على البطلان والتحريم»، «وأما العقود والشروط والمعاملات فهي عفو حتى يحرمها» (ج٣/ص١٠٧)، «فكلُّ شَرْط وعَقْد ومعاملة سكت عنها فإنه لا يجوز القولُ بتحريمها» (ج٣/ص١٠٨). وفي حدّ الغرر: «ولم يأتِ عنه حرف واحد أنه نهى عن بيع المعدوم، وإنما نهى عن بيع الغرر، والغررُ شيء وهذا شيء» (ج٣/ص٦٠)، «بل الذي وَرَدت به السنة النهي عن بيع الغَرَر، وهو ما لا يُقْدَر على تسليمه، سواء كان موجودًا أو معدومًا»، «فهو غَرَر ومُخاطرة وقمار»، «وهذا من الميْسِر الذي حرّمه اللَّه ورسوله» (ج٣/ص٢٠٧).',
  verification_status = 'verified'
WHERE id = '984d613a-3d42-41bd-99e7-cb6c4a6a91fd'
  AND reference = 'القرآن الكريم؛ إعلام الموقعين | الكلمات المفتاحية: معاملات، مال، غرر'
  AND evidence = 'قال تعالى: ﴿لَا تَأْكُلُوا أَمْوَالَكُم بَيْنَكُم بِالْبَاطِلِ﴾ [النساء: 29].'
  AND answer = 'أن تخلو من الربا والغرر والظلم وأكل المال بالباطل.';

-- a66f8b19 | ما فضل ذكر الله؟
UPDATE qa_questions SET
  answer = 'الذكرُ عند ابن القيم في الوابل الصيب بابٌ واسع: «وفي الذكر نحوٌ من مائة فائدة»، عدَّ منها أنه «يطرد الشيطان ويَقْمَعُه ويَكْسِرُه»، و«يُرضِي الرحمن»، و«يزيل الهم والغم عن القلب»، و«يجلب للقلب الفرح والسرور والبَسْط»، و«يورثه المحبة التي هي روح الإسلام، وقطبُ رَحى الدين، ومدار السعادة والنجاة» إذ «جعل سبب المحبة دوام الذكر»، و«يورثه المراقبة حتى يُدْخِلَه في باب الإحسان، فيعبد الله كأنه يراه، ولا سبيل للغافل عن الذِّكر إلى مقام الإحسان»، و«يورثه الإنابة، وهي الرجوع إلى الله». وطمأنينةُ القلوب في الآية مقرونةٌ بالإيمان: ﴿ٱلَّذِينَ ءَامَنُوا۟ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ٱللَّهِ ۗ أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ﴾.',
  reference = 'القرآن الكريم: الرعد ٢٨؛ الوابل الصيب ورافع الكلم الطيب لابن القيم (ت ابن قائد، دار عطاءات العلم): ص٩٤-٩٥ (فصل في فوائد الذكر) | الكلمات المفتاحية: ذكر، دعاء، طمأنينة',
  evidence = 'قال ابن القيم في الوابل الصيب: «وفي الذكر نحوٌ من مائة فائدة: إحداها: أنه يطرد الشيطان ويَقْمَعُه ويَكْسِرُه. الثانية: أنه يُرضِي الرحمن. الثالثة: أنه يزيل الهم والغم عن القلب. الرابعة: أنه يجلب للقلب الفرح والسرور والبَسْط. الخامسة: أنه يُقَوِّي القلب والبدن. السادسة: أنه يُنَوِّر الوجه والقلب» (ص٩٤)، «التاسعة: أنه يورثه المحبة التي هي روح الإسلام، وقطبُ رَحى الدين، ومدار السعادة والنجاة»، «وجعل سبب المحبة دوام الذكر؛ فمن أراد أن ينال محبة الله» (ص٩٤)، «العاشرة: أنه يورثه المراقبة حتى يُدْخِلَه في باب الإحسان، فيعبد الله كأنه يراه، ولا سبيل للغافل عن الذِّكر إلى مقام الإحسان»، «الحادية عشرة: أنه يورثه الإنابة، وهي الرجوع إلى الله»، «الثانية عشرة: أنه يُورِثه القُرْبَ منه» (ص٩٥).',
  verification_status = 'verified'
WHERE id = 'a66f8b19-2cfa-4320-a873-eb877ac49005'
  AND reference = 'القرآن الكريم؛ الوابل الصيب | الكلمات المفتاحية: ذكر، دعاء، طمأنينة'
  AND evidence = 'قال تعالى: ﴿أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ﴾ [الرعد: 28].'
  AND answer = 'ذكر الله من أعظم العبادات وأيسرها، وبه تطمئن القلوب.';

-- 87bc99af | ما أساس التربية الإيمانية؟
UPDATE qa_questions SET
  answer = 'أساسُها عند ابن القيم في مدارج السالكين الاتِّباعُ لا الرأي: «فَإِنَّ تَزْكِيَةَ النُّفُوسِ مُسَلَّمٌ إِلَى الرُّسُلِ»، «فَالرُّسُلُ أَطِبَّاءُ الْقُلُوبِ. فَلَا سَبِيلَ إِلَى تَزْكِيَتِهَا وَصَلَاحِهَا إِلَّا مِنْ طَرِيقِهِمْ»؛ فمن «زَكَّى نَفْسَهُ بِالرِّيَاضَةِ وَالْمُجَاهَدَةِ وَالْخَلْوَةِ، الَّتِي لَمْ يَجِئْ بِهَا الرُّسُلُ: فَهُوَ كَالْمَرِيضِ الَّذِي عَالَجَ نَفْسَهُ بِرَأْيِهِ». وقد قابل الله بين الفلاح والخيبة بعد أن ألهم النفسَ الأمرين: ﴿وَنَفْسٍۢ وَمَا سَوَّىٰهَا﴾ ﴿فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا﴾ ﴿قَدْ أَفْلَحَ مَن زَكَّىٰهَا﴾ ﴿وَقَدْ خَابَ مَن دَسَّىٰهَا﴾؛ والتزكيةُ عنده رفعُ النفس «بِآدَابِهِ الَّتِي أَدَّبَ بِهَا رُسُلَهُ وَأَنْبِيَاءَهُ وَأَوْلِيَاءَهُ. وَهِيَ التَّقْوَى». وتعويدُ النفس داخلٌ في ذلك؛ فالخلق «يُمْكِنُ أَنْ يَقَعَ كَسْبِيًّا بِالتَّخَلُّقِ وَالتَّكَلُّفِ. حَتَّى يَصِيرَ لَهُ سَجِيَّةً وَمَلَكَةً».',
  reference = 'القرآن الكريم: الشمس ٧-١٠، والجمعة ٢؛ مدارج السالكين لابن القيم (ت المعتصم بالله البغدادي، دار الكتاب العربي): ج٢/ص٣٠٠ (فصل تغيير الأخلاق التي طبعت النفوس عليها)، وج٢/ص٣٦١ (حقيقة الأدب وتفسير آية الشمس) | الكلمات المفتاحية: تربية، تزكية، مراقبة',
  evidence = 'قال ابن القيم في مدارج السالكين: «فَإِنَّ تَزْكِيَةَ النُّفُوسِ مُسَلَّمٌ إِلَى الرُّسُلِ. وَإِنَّمَا بَعَثَهُمُ اللَّهُ لِهَذِهِ التَّزْكِيَةِ وَوَلَّاهُمْ إِيَّاهَا. وَجَعَلَهَا عَلَى أَيْدِيهِمْ دَعْوَةً، وَتَعْلِيمًا وَبَيَانًا، وَإِرْشَادًا، لَا خَلْقًا وَلَا إِلْهَامًا. فَهُمُ الْمَبْعُوثُونَ لِعِلَاجِ نُفُوسِ الْأُمَمِ»، واستدلّ بقوله تعالى ﴿هُوَ ٱلَّذِى بَعَثَ فِى ٱلْأُمِّيِّۦنَ رَسُولًۭا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ﴾ [الجمعة: ٢]، ثم قال: «وَتَزْكِيَةُ النُّفُوسِ: أَصْعَبُ مِنْ عِلَاجِ الْأَبْدَانِ وَأَشَدُّ. فَمَنْ زَكَّى نَفْسَهُ بِالرِّيَاضَةِ وَالْمُجَاهَدَةِ وَالْخَلْوَةِ، الَّتِي لَمْ يَجِئْ بِهَا الرُّسُلُ: فَهُوَ كَالْمَرِيضِ الَّذِي عَالَجَ نَفْسَهُ بِرَأْيِهِ»، «فَالرُّسُلُ أَطِبَّاءُ الْقُلُوبِ. فَلَا سَبِيلَ إِلَى تَزْكِيَتِهَا وَصَلَاحِهَا إِلَّا مِنْ طَرِيقِهِمْ. وَعَلَى أَيْدِيهِمْ، وَبِمَحْضِ الِانْقِيَادِ، وَالتَّسْلِيمِ لَهُمْ»، وأن الخُلُق «يُمْكِنُ أَنْ يَقَعَ كَسْبِيًّا بِالتَّخَلُّقِ وَالتَّكَلُّفِ. حَتَّى يَصِيرَ لَهُ سَجِيَّةً وَمَلَكَةً» (ج٢/ص٣٠٠). وفي تفسير آية الشمس: «ثُمَّ خَصَّ بِالْفَلَاحِ مَنْ زَكَّاهَا فَنَمَّاهَا وَعَلَّاهَا. وَرَفَعَهَا بِآدَابِهِ الَّتِي أَدَّبَ بِهَا رُسُلَهُ وَأَنْبِيَاءَهُ وَأَوْلِيَاءَهُ. وَهِيَ التَّقْوَى. ثُمَّ حَكَمَ بِالشَّقَاءِ عَلَى مَنْ دَسَّاهَا فَأَخْفَاهَا وَحَقَّرَهَا. وَصَغَّرَهَا وَقَمَعَهَا بِالْفُجُورِ» (ج٢/ص٣٦١).',
  verification_status = 'verified'
WHERE id = '87bc99af-e8f3-4f7e-b366-a919214759ad'
  AND reference = 'القرآن الكريم؛ مدارج السالكين | الكلمات المفتاحية: تربية، تزكية، مراقبة'
  AND evidence = 'قال تعالى: ﴿قَدْ أَفْلَحَ مَن زَكَّاهَا﴾ [الشمس: 9].'
  AND answer = 'تعظيم الله ومحبته ومراقبته، وتعويد النفس على الطاعة والصبر.';
